"use client"

import * as React from "react"
import { cn } from "@/lib/utils"

import {
  createGridData,
  DataGrid,
  dataGridCellTypes,
  formatCellRef,
  formatRange,
  isEmptyValue,
  isFormulaText,
  normalizeRange,
  parseCellRef,
  type CellValue,
  type DataGridCellType,
  type DataGridEditMove,
  type DataGridEditorContext,
  type DataGridProps,
  type GridChange,
  type GridColumn,
  type GridData,
  type GridRange,
} from "@/components/standard/data-grid"
import {
  evaluatesFormula,
  evaluatesVariables,
  formatsCalcValue,
  tokenizesFormula,
  type CalcFunctions,
  type CalcResult,
  type CalcToken,
  type CalcValue,
  type CalcVariables,
} from "@/components/standard/input-calculator-model"

export * from "@/components/standard/data-grid"

/** Result of every formula cell, keyed by its A1 name ("D4"). */
export type SpreadsheetResults = Record<string, CalcResult>

type SheetOptions = {
  /** Named values formulas can use next to cell references, e.g. `{ taxRate: 0.08 }`. */
  variables?: CalcVariables
  /** Extra functions, or replacements for built-ins. Names ignore case. */
  functions?: CalcFunctions
}

/** Every filled cell as a variable named by its A1 reference, plus your own names. */
function sheetVariablesOf(data: GridData, variables?: CalcVariables) {
  const sheet: CalcVariables = { ...variables }
  data.rows.forEach((row, rowIndex) => {
    const cells = data.cells[row.id]
    if (!cells) return
    data.columns.forEach((column, colIndex) => {
      const value = cells[column.id]
      if (!isEmptyValue(value)) {
        sheet[formatCellRef({ row: rowIndex, col: colIndex })] =
          value as CalcValue
      }
    })
  })
  return sheet
}

/**
 * Works out every formula in the grid. Cells are named A1, B2… by their
 * position; text starting with "=" is a formula. No React: use it on a server
 * to read a sheet's totals.
 */
export function evaluatesSheet(
  data: GridData,
  { variables, functions }: SheetOptions = {}
): SpreadsheetResults {
  return evaluatesVariables({
    variables: sheetVariablesOf(data, variables),
    functions,
    references: true,
  })
}

// ---------------------------------------------------------------------------
// Cells

function formatsResult(value: CalcValue) {
  return typeof value === "number"
    ? value.toLocaleString("en-US", { maximumFractionDigits: 10 })
    : formatsCalcValue(value)
}

function displayOf(
  result: CalcResult | undefined,
  format: (value: CalcValue) => string
) {
  if (!result || result.status === "empty") return ""
  return result.status === "ok" ? format(result.value) : result.error.code
}

function FormulaResult({
  result,
  format,
}: {
  result: CalcResult | undefined
  format: (value: CalcValue) => string
}) {
  if (!result || result.status === "empty") return null
  if (result.status === "error") {
    return (
      <span
        data-formula="error"
        title={result.error.message}
        className="ml-auto truncate font-medium text-destructive"
      >
        {result.error.code}
      </span>
    )
  }
  const { value } = result
  return (
    <span
      data-formula="ok"
      className={cn(
        "truncate",
        typeof value === "number" && "ml-auto tabular-nums",
        typeof value === "boolean" && "mx-auto"
      )}
    >
      {format(value)}
    </span>
  )
}

/** Colours for the formula editor's tokens. */
const TOKEN_CLASSES =
  "[&_[data-token=equals]]:text-muted-foreground [&_[data-token=number]]:text-sky-600 dark:[&_[data-token=number]]:text-sky-400 [&_[data-token=string]]:text-amber-600 dark:[&_[data-token=string]]:text-amber-400 [&_[data-token=boolean]]:text-violet-600 dark:[&_[data-token=boolean]]:text-violet-400 [&_[data-token=name]]:text-emerald-600 dark:[&_[data-token=name]]:text-emerald-400 [&_[data-token=function]]:font-semibold [&_[data-token=function]]:text-fuchsia-600 dark:[&_[data-token=function]]:text-fuchsia-400 [&_[data-token=operator]]:text-muted-foreground [&_[data-token=paren]]:text-muted-foreground"

/** Excel-style colours, one per distinct cell or range in the formula being edited. */
const REFERENCE_COLORS = [
  {
    text: "text-sky-600 dark:text-sky-400",
    box: "border-sky-500 bg-sky-500/10",
  },
  {
    text: "text-rose-600 dark:text-rose-400",
    box: "border-rose-500 bg-rose-500/10",
  },
  {
    text: "text-violet-600 dark:text-violet-400",
    box: "border-violet-500 bg-violet-500/10",
  },
  {
    text: "text-emerald-600 dark:text-emerald-400",
    box: "border-emerald-500 bg-emerald-500/10",
  },
  {
    text: "text-amber-600 dark:text-amber-400",
    box: "border-amber-500 bg-amber-500/10",
  },
  {
    text: "text-pink-600 dark:text-pink-400",
    box: "border-pink-500 bg-pink-500/10",
  },
  {
    text: "text-teal-600 dark:text-teal-400",
    box: "border-teal-500 bg-teal-500/10",
  },
]

type FormulaReference = GridRange & {
  color: number
  /** Start offsets of the tokens that spell it: `B2`, or `B2`, `:` and `C9`. */
  tokens: number[]
}

/** The cells and ranges a formula points at, each with its colour. */
function referencesIn(tokens: CalcToken[]): FormulaReference[] {
  const solid = tokens.filter((token) => token.type !== "space")
  const colors = new Map<string, number>()
  const found: FormulaReference[] = []

  for (let index = 0; index < solid.length; index += 1) {
    const token = solid[index]
    if (token.type !== "reference") continue
    const from = parseCellRef(token.text)
    if (!from) continue

    let to = from
    const starts = [token.start]
    const colon = solid[index + 1]
    const end = solid[index + 2]
    const endRef =
      colon?.type === "colon" && end?.type === "reference"
        ? parseCellRef(end.text)
        : null
    if (endRef) {
      to = endRef
      starts.push(colon.start, end.start)
      index += 2
    }

    const range = normalizeRange(from, to)
    const key = formatRange(range)
    if (!colors.has(key)) colors.set(key, colors.size % REFERENCE_COLORS.length)
    found.push({ ...range, color: colors.get(key)!, tokens: starts })
  }
  return found
}

/**
 * Holds the references of the formula being edited. Cells subscribe on their
 * own, so typing repaints the outlines without re-rendering the whole grid.
 */
function createsReferenceStore() {
  let references: FormulaReference[] = []
  const listeners = new Set<() => void>()
  return {
    get: () => references,
    set(next: FormulaReference[]) {
      if (next.length === 0 && references.length === 0) return
      references = next
      for (const listener of listeners) listener()
    },
    subscribe(listener: () => void) {
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
  }
}

type ReferenceStore = ReturnType<typeof createsReferenceStore>

const NO_REFERENCES: FormulaReference[] = []

/** A coloured outline on cells the edited formula points at; ranges get one box. */
function ReferenceOutline({
  store,
  row,
  col,
}: {
  store: ReferenceStore
  row: number
  col: number
}) {
  const references = React.useSyncExternalStore(
    store.subscribe,
    store.get,
    () => NO_REFERENCES
  )
  const hit = references.find(
    (range) =>
      row >= range.top &&
      row <= range.bottom &&
      col >= range.left &&
      col <= range.right
  )
  if (!hit) return null

  return (
    <span
      aria-hidden
      data-formula-reference={formatRange(hit)}
      className={cn(
        "pointer-events-none absolute inset-0 border-0 border-dashed",
        REFERENCE_COLORS[hit.color].box,
        row === hit.top && "border-t-2",
        row === hit.bottom && "border-b-2",
        col === hit.left && "border-l-2",
        col === hit.right && "border-r-2"
      )}
    />
  )
}

function movesFrom(event: React.KeyboardEvent): DataGridEditMove | null {
  if (event.key === "Enter") return event.shiftKey ? "up" : "down"
  if (event.key === "Tab") return event.shiftKey ? "left" : "right"
  return null
}

/**
 * The grid's text editor, plus formula colouring and a live result under the
 * cell while the text starts with "=".
 */
function FormulaEditor({
  context,
  preview,
  format,
  store,
}: {
  context: DataGridEditorContext
  preview: (formula: string, ref: string) => CalcResult
  format: (value: CalcValue) => string
  store: ReferenceStore
}) {
  const [draft, setDraft] = React.useState(context.initialText ?? context.text)
  const inputRef = React.useRef<HTMLInputElement>(null)
  const highlightRef = React.useRef<HTMLSpanElement>(null)
  const ref = formatCellRef({ row: context.rowIndex, col: context.colIndex })

  const draftRef = React.useRef(draft)
  React.useLayoutEffect(() => {
    draftRef.current = draft
  })
  const { register, commit, parse } = context
  React.useEffect(() => {
    register(() => commit(parse(draftRef.current), "none"))
    return () => register(null)
  }, [register, commit, parse])

  React.useLayoutEffect(() => {
    const input = inputRef.current
    if (!input) return
    input.focus({ preventScroll: true })
    input.setSelectionRange(input.value.length, input.value.length)
  }, [])

  const isFormula = isFormulaText(draft)
  const result = isFormula ? preview(draft, ref) : null
  const error = result?.status === "error" ? result.error : null
  const tokens = React.useMemo(
    () => (isFormulaText(draft) ? tokenizesFormula(draft) : []),
    [draft]
  )
  const references = React.useMemo(() => referencesIn(tokens), [tokens])
  const colorAt = new Map(
    references.flatMap((reference) =>
      reference.tokens.map((start) => [start, reference.color])
    )
  )

  React.useEffect(() => store.set(references), [store, references])
  React.useEffect(() => () => store.set([]), [store])

  return (
    <>
      <div className="absolute inset-0 grid items-center bg-background">
        {isFormula ? (
          <span
            ref={highlightRef}
            aria-hidden
            className={cn(
              "pointer-events-none col-start-1 row-start-1 overflow-hidden px-2 text-sm whitespace-pre",
              TOKEN_CLASSES
            )}
          >
            {tokens.map((token) => (
              <span
                key={token.start}
                data-token={token.type}
                className={cn(
                  colorAt.has(token.start) &&
                    REFERENCE_COLORS[colorAt.get(token.start)!].text,
                  error &&
                    !error.incomplete &&
                    error.start !== undefined &&
                    error.end !== undefined &&
                    token.type !== "space" &&
                    token.start < error.end &&
                    token.end > error.start &&
                    "underline decoration-destructive decoration-wavy"
                )}
              >
                {token.text}
              </span>
            ))}
          </span>
        ) : null}
        <input
          ref={inputRef}
          data-grid-editor
          type="text"
          value={draft}
          spellCheck={false}
          autoComplete="off"
          aria-label={`Edit ${ref}`}
          aria-describedby={result ? `${ref}-formula-preview` : undefined}
          className={cn(
            "col-start-1 row-start-1 size-full min-w-0 bg-transparent px-2 text-sm outline-none",
            isFormula && "text-transparent caret-foreground",
            !isFormula &&
              context.column.type === "number" &&
              "text-right tabular-nums"
          )}
          onChange={(event) => setDraft(event.target.value)}
          onScroll={(event) => {
            if (highlightRef.current) {
              highlightRef.current.scrollLeft = event.currentTarget.scrollLeft
            }
          }}
          onBlur={() => commit(parse(draft), "none")}
          onKeyDown={(event) => {
            event.stopPropagation()
            const move = movesFrom(event)
            if (move) {
              event.preventDefault()
              commit(parse(draft), move)
            } else if (event.key === "Escape") {
              event.preventDefault()
              context.cancel()
            }
          }}
        />
      </div>
      {result && result.status !== "empty" ? (
        <div
          id={`${ref}-formula-preview`}
          role="status"
          className={cn(
            "pointer-events-none absolute top-full left-0 z-50 mt-1 max-w-72 truncate rounded-md bg-popover px-2 py-1 font-mono text-xs text-popover-foreground shadow-md ring-1 ring-foreground/10",
            error && !error.incomplete && "text-destructive"
          )}
        >
          {result.status === "ok"
            ? `= ${format(result.value)}`
            : error!.incomplete
              ? "…"
              : `${error!.code} ${error!.message}`}
        </div>
      ) : null}
    </>
  )
}

/** Numbers in the selection, with formulas read as their results. */
export type SpreadsheetSelectionStats = {
  sum: number
  average: number
  /** Cells holding a number. */
  count: number
}

/** Adds up the numbers in a range: typed numbers, numeric text, and formula results. */
function statsOf(
  data: GridData,
  range: GridRange,
  results: SpreadsheetResults
) {
  let sum = 0
  let count = 0
  for (let row = range.top; row <= range.bottom; row += 1) {
    const cells = data.rows[row] && data.cells[data.rows[row].id]
    if (!cells) continue
    for (let col = range.left; col <= range.right; col += 1) {
      const column = data.columns[col]
      if (!column) continue
      const value = cells[column.id]
      let number: number | null = null
      if (typeof value === "number") {
        number = value
      } else if (typeof value === "string") {
        // Guard a copy so the numeric-text branch keeps `value` as a string.
        const text: CellValue = value
        if (isFormulaText(text)) {
          const result = results[formatCellRef({ row, col })]
          if (result?.status === "ok" && typeof result.value === "number")
            number = result.value
        } else if (value.trim() !== "" && Number.isFinite(Number(value))) {
          number = Number(value)
        }
      }
      if (number !== null) {
        sum += number
        count += 1
      }
    }
  }
  return { sum, average: count ? sum / count : 0, count }
}

function formatsSelectionStats(
  { sum, average, count }: SpreadsheetSelectionStats,
  format: (value: CalcValue) => string
) {
  return (
    <>
      <span>Avg {format(average)}</span>
      <span>Count {count}</span>
      <span>Sum {format(sum)}</span>
    </>
  )
}

// ---------------------------------------------------------------------------
// Spreadsheet

export type SpreadsheetProps = DataGridProps &
  SheetOptions & {
    /** Display text for formula results. Numbers default to en-US grouping. */
    formatResult?: (value: CalcValue) => string
    /** Every formula's result, after each change. */
    onResults?: (results: SpreadsheetResults) => void
    /**
     * Adds up the selection in the footer once it holds two or more numbers.
     * Pass a function to write your own text, or `false` to hide it.
     */
    selectionSummary?:
      boolean | ((stats: SpreadsheetSelectionStats) => React.ReactNode)
    /**
     * The bar under the grid that holds sheet tabs and the selection summary.
     * Pass content to show it at the start of the bar, or `false` to hide the bar.
     */
    footer?: boolean | React.ReactNode
    /** Sheets shown as tabs in the footer, like workbook tabs. Each sheet is its own grid. */
    sheets?: SpreadsheetSheet[]
    /** Starting sheets when `sheets` is not controlled. */
    defaultSheets?: SpreadsheetSheet[]
    onSheetsChange?: (sheets: SpreadsheetSheet[]) => void
    /** Id of the sheet on screen. */
    activeSheet?: string
    defaultActiveSheet?: string
    onActiveSheetChange?: (id: string) => void
  }

/** One tab of a workbook. Formulas reference cells on their own sheet. */
export type SpreadsheetSheet = { id: string; name: string; data: GridData }

/**
 * A Data Grid whose cells take formulas: type `=SUM(B2:B9)` or `=B2 * $C$1`
 * and the cell shows the result, recalculated as other cells change. Cells
 * are named by position (A1, B2…), dragging the fill handle moves relative
 * references, and the value bar shows the formula behind the active cell.
 * Everything else (undo, copy and paste, sort, adapters) is the Data Grid.
 */
export function Spreadsheet({
  sheets,
  defaultSheets,
  onSheetsChange,
  activeSheet,
  defaultActiveSheet,
  onActiveSheetChange,
  ...props
}: SpreadsheetProps) {
  const [ownSheets, setOwnSheets] = React.useState(defaultSheets)
  const workbook = sheets ?? ownSheets
  const [ownActive, setOwnActive] = React.useState(
    defaultActiveSheet ?? workbook?.[0]?.id
  )

  if (!workbook || workbook.length === 0) return <SpreadsheetGrid {...props} />

  const activeId = activeSheet ?? ownActive
  const active = workbook.find((sheet) => sheet.id === activeId) ?? workbook[0]

  const changesSheets = (next: SpreadsheetSheet[]) => {
    if (sheets === undefined) setOwnSheets(next)
    onSheetsChange?.(next)
  }
  const selectsSheet = (id: string) => {
    if (activeSheet === undefined) setOwnActive(id)
    onActiveSheetChange?.(id)
  }

  const { onValueChange, onKeyDown, footer = true, ...gridProps } = props
  const tabs = (
    <SheetTabs
      sheets={workbook}
      activeId={active.id}
      readOnly={props.readOnly}
      onSelect={selectsSheet}
      onChange={changesSheets}
    />
  )

  return (
    <SpreadsheetGrid
      // Each sheet keeps its own selection, undo history and formula results.
      key={active.id}
      {...gridProps}
      value={active.data}
      defaultValue={undefined}
      onValueChange={(next, changes) => {
        changesSheets(
          workbook.map((sheet) =>
            sheet.id === active.id ? { ...sheet, data: next } : sheet
          )
        )
        onValueChange?.(next, changes)
      }}
      onKeyDown={(event) => {
        onKeyDown?.(event)
        // Ctrl+PageUp / Ctrl+PageDown step through sheets, as in Excel.
        if (
          !event.ctrlKey ||
          (event.key !== "PageUp" && event.key !== "PageDown")
        )
          return
        event.preventDefault()
        const index = workbook.indexOf(active)
        const next = workbook[index + (event.key === "PageUp" ? -1 : 1)]
        if (next) selectsSheet(next.id)
      }}
      footer={
        footer === false ? (
          false
        ) : (
          <>
            {tabs}
            {footer === true ? null : footer}
          </>
        )
      }
    />
  )
}

function createsSheetId() {
  return `sheet-${Math.random().toString(36).slice(2, 10)}`
}

function SheetTabs({
  sheets,
  activeId,
  readOnly,
  onSelect,
  onChange,
}: {
  sheets: SpreadsheetSheet[]
  activeId: string
  readOnly?: boolean
  onSelect: (id: string) => void
  onChange: (sheets: SpreadsheetSheet[]) => void
}) {
  const [renaming, setRenaming] = React.useState<string | null>(null)

  const addsSheet = () => {
    const taken = new Set(sheets.map((sheet) => sheet.name))
    let number = sheets.length + 1
    while (taken.has(`Sheet${number}`)) number += 1
    const sheet = {
      id: createsSheetId(),
      name: `Sheet${number}`,
      data: createGridData({ columns: 8, rows: 40 }),
    }
    onChange([...sheets, sheet])
    onSelect(sheet.id)
  }

  const removesSheet = (id: string) => {
    const index = sheets.findIndex((sheet) => sheet.id === id)
    const rest = sheets.filter((sheet) => sheet.id !== id)
    onChange(rest)
    if (id === activeId) onSelect(rest[Math.max(0, index - 1)].id)
  }

  const renamesSheet = (id: string, name: string) => {
    setRenaming(null)
    const trimmed = name.trim()
    if (!trimmed) return
    onChange(
      sheets.map((sheet) =>
        sheet.id === id ? { ...sheet, name: trimmed } : sheet
      )
    )
  }

  return (
    <div
      role="tablist"
      aria-label="Sheets"
      className="-ml-3 flex min-w-0 items-stretch self-stretch overflow-x-auto"
    >
      {sheets.map((sheet) => {
        const selected = sheet.id === activeId
        return (
          <div
            key={sheet.id}
            className={cn(
              "relative flex shrink-0 items-center border-r border-border",
              selected
                ? "bg-background text-foreground after:absolute after:inset-x-0 after:bottom-0 after:h-0.5 after:bg-primary"
                : "hover:bg-muted/50 hover:text-foreground"
            )}
          >
            {renaming === sheet.id ? (
              <input
                autoFocus
                aria-label="Sheet name"
                defaultValue={sheet.name}
                className="w-24 bg-transparent px-3 text-xs outline-none"
                onFocus={(event) => event.currentTarget.select()}
                onBlur={(event) =>
                  renamesSheet(sheet.id, event.currentTarget.value)
                }
                onKeyDown={(event) => {
                  event.stopPropagation()
                  if (event.key === "Enter") event.currentTarget.blur()
                  if (event.key === "Escape") setRenaming(null)
                }}
              />
            ) : (
              <button
                type="button"
                role="tab"
                aria-selected={selected}
                className="h-full px-3 outline-none focus-visible:underline"
                onClick={() => onSelect(sheet.id)}
                onDoubleClick={() => {
                  if (!readOnly) setRenaming(sheet.id)
                }}
              >
                {sheet.name}
              </button>
            )}
            {/* Only the active tab can close, so tabs never shift under the pointer. */}
            {selected && !readOnly && sheets.length > 1 && renaming !== sheet.id ? (
              <button
                type="button"
                aria-label={`Delete ${sheet.name}`}
                className="mr-1.5 -ml-1.5 flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:bg-muted hover:text-foreground"
                onClick={() => removesSheet(sheet.id)}
              >
                ×
              </button>
            ) : null}
          </div>
        )
      })}
      {readOnly ? null : (
        <button
          type="button"
          aria-label="Add sheet"
          className="flex w-8 shrink-0 items-center justify-center text-sm hover:bg-muted/50 hover:text-foreground"
          onClick={addsSheet}
        >
          +
        </button>
      )}
    </div>
  )
}

function SpreadsheetGrid({
  value,
  defaultValue,
  onValueChange,
  cellTypes,
  variables,
  functions,
  formatResult = formatsResult,
  onResults,
  selectionSummary = true,
  footer = true,
  onSelectionChange,
  label = "Spreadsheet",
  ...props
}: Omit<
  SpreadsheetProps,
  | "sheets"
  | "defaultSheets"
  | "onSheetsChange"
  | "activeSheet"
  | "defaultActiveSheet"
  | "onActiveSheetChange"
>) {
  // The grid owns editing; this mirror only feeds the formulas.
  const [initial] = React.useState(
    () => defaultValue ?? createGridData({ columns: 8, rows: 40 })
  )
  const [mirror, setMirror] = React.useState(initial)
  const data = value ?? mirror
  const [references] = React.useState(createsReferenceStore)
  const [selected, setSelected] = React.useState<GridRange | null>(null)

  const sheetVariables = React.useMemo(
    () => sheetVariablesOf(data, variables),
    [data, variables]
  )
  const results = React.useMemo(
    () =>
      evaluatesVariables({
        variables: sheetVariables,
        functions,
        references: true,
      }),
    [sheetVariables, functions]
  )

  const onResultsRef = React.useRef(onResults)
  React.useEffect(() => {
    onResultsRef.current = onResults
  })
  React.useEffect(() => {
    onResultsRef.current?.(results)
  }, [results])

  const preview = React.useCallback(
    (formula: string, ref: string) =>
      evaluatesFormula(formula, {
        variables: { ...sheetVariables, [ref]: formula },
        functions,
        references: true,
      }),
    [sheetVariables, functions]
  )

  const types = React.useMemo(() => {
    // fitWidth has no cell position, so it sizes a formula by its latest result.
    const displayByFormula = new Map<string, string>()
    for (const result of Object.values(results)) {
      displayByFormula.set(result.formula, displayOf(result, formatResult))
    }

    const wrapped: Record<string, DataGridCellType> = {}
    for (const [name, type] of Object.entries({
      ...dataGridCellTypes,
      ...cellTypes,
    })) {
      const plain = (value: CellValue, column: GridColumn) =>
        type.format
          ? type.format(value, column)
          : value === null
            ? ""
            : String(value)
      // Text-like types get the formula editor; select, date and custom editors keep theirs.
      const takesFormulas = type.edit === undefined || name === "number"

      wrapped[name] = {
        ...type,
        render: (context) => {
          const ref = formatCellRef({
            row: context.rowIndex,
            col: context.colIndex,
          })
          const content = isFormulaText(context.value) ? (
            <FormulaResult result={results[ref]} format={formatResult} />
          ) : type.render ? (
            type.render(context)
          ) : (
            <span className="truncate">
              {plain(context.value, context.column)}
            </span>
          )
          return (
            <>
              {content}
              <ReferenceOutline
                store={references}
                row={context.rowIndex}
                col={context.colIndex}
              />
            </>
          )
        },
        edit: takesFormulas
          ? (context) => (
              <FormulaEditor
                context={context}
                preview={preview}
                format={formatResult}
                store={references}
              />
            )
          : type.edit,
        fitWidth: (context) => {
          if (isFormulaText(context.value)) {
            return (
              context.measure(
                displayByFormula.get(context.value) ?? context.text
              ) + 17
            )
          }
          return type.fitWidth
            ? type.fitWidth(context)
            : context.measure(context.text) + 17
        },
      }
    }
    return wrapped
  }, [cellTypes, results, formatResult, preview, references])

  const stats = React.useMemo(
    () =>
      selectionSummary && selected ? statsOf(data, selected, results) : null,
    [selectionSummary, selected, data, results]
  )
  const summary =
    stats && stats.count >= 2
      ? typeof selectionSummary === "function"
        ? selectionSummary(stats)
        : formatsSelectionStats(stats, formatResult)
      : null

  const handlesValueChange = (next: GridData, changes: GridChange[]) => {
    if (value === undefined) setMirror(next)
    onValueChange?.(next, changes)
  }

  const handlesSelectionChange = (range: GridRange) => {
    setSelected(range)
    onSelectionChange?.(range)
  }

  return (
    <DataGrid
      {...props}
      data-slot="spreadsheet"
      label={label}
      value={value}
      defaultValue={value === undefined ? initial : undefined}
      onValueChange={handlesValueChange}
      onSelectionChange={handlesSelectionChange}
      cellTypes={types}
      footer={
        footer === false ? undefined : (
          <>
            {footer === true ? null : footer}
            {/* Stays mounted while empty so the grid keeps its height as the selection changes. */}
            <div
              aria-live="polite"
              className="ml-auto flex shrink-0 items-center gap-4 font-mono"
            >
              {selectionSummary ? summary : null}
            </div>
          </>
        )
      }
    />
  )
}

/**
 * Headless engine for the Input Calculator: it reads a spreadsheet-style
 * formula such as `=ROUND(price * qty * (1 + tax), 2)` and returns its value.
 * Nothing here touches React, so the same functions work in a server action,
 * a test, or a worker.
 *
 * - Operators: + - * / ^ & (join text), = <> < > <= >= and postfix %.
 *   Precedence follows maths, not Excel: -2^2 is -4 and 2^3^2 is 512.
 * - Values: numbers (1.5, .5, 2e3), "text" ("" escapes a quote), TRUE, FALSE.
 * - Names resolve against `variables`, ignoring case. A variable whose value
 *   is a string starting with "=" is itself a formula and may use other
 *   variables; loops come back as #CIRC!.
 * - With `references`, A1-style names are spreadsheet cells: a missing one
 *   is empty, `$` pins a row or column, and `B2:C9` is a range for SUM() etc.
 *   `evaluatesVariables` works out a whole sheet of them with one cache.
 * - Functions ignore case too. See CALC_FUNCTION_NAMES for the built-ins;
 *   `functions` adds your own or replaces one.
 * - Errors come back as Excel-style codes (#DIV/0!, #NAME?, #VALUE!, #NUM!)
 *   with a message and, when it points at the text, a start/end range.
 */

export type CalcValue = number | string | boolean

/** What a function argument can be: one value, or a list from a variable. */
export type CalcArg = CalcValue | CalcValue[]

/** A value, a list (for SUM, AVERAGE…), or a formula string starting with "=". */
export type CalcVariable = CalcValue | CalcValue[]

export type CalcVariables = Record<string, CalcVariable>

export type CalcFunction = (...args: CalcArg[]) => CalcValue

export type CalcFunctions = Record<string, CalcFunction>

export type CalcErrorCode =
  | "#ERROR!"
  | "#NAME?"
  | "#VALUE!"
  | "#DIV/0!"
  | "#NUM!"
  | "#N/A"
  | "#CIRC!"

export type CalcErrorInfo = {
  code: CalcErrorCode
  message: string
  /** Character range in the formula the error points at, when it has one. */
  start?: number
  end?: number
  /** True when the formula just isn't finished yet, e.g. `1 +` or `SUM(1`. */
  incomplete?: boolean
}

export type CalcResult =
  | { status: "empty"; formula: string; dependencies: string[] }
  | {
      status: "ok"
      formula: string
      value: CalcValue
      /** Variables the formula reads, spelled as they are declared. */
      dependencies: string[]
    }
  | {
      status: "error"
      formula: string
      error: CalcErrorInfo
      dependencies: string[]
    }

export type CalcOptions = {
  variables?: CalcVariables
  functions?: CalcFunctions
  /**
   * Evaluate only text that starts with "=", like a spreadsheet cell. Anything
   * else is a literal: "42" is 42, "15%" is 0.15, "TRUE" is true, the rest is text.
   */
  requireEquals?: boolean
  /**
   * Treat A1-style names (B2, $C$9) as spreadsheet cells: a missing one is
   * empty ("" as text, 0 as a number) instead of #NAME?.
   */
  references?: boolean
}

/** Throw this from a custom function to return a specific error code. */
export class CalcError extends Error {
  code: CalcErrorCode
  start?: number
  end?: number
  incomplete?: boolean

  constructor(
    code: CalcErrorCode,
    message: string,
    range?: { start: number; end: number; incomplete?: boolean }
  ) {
    super(message)
    this.name = "CalcError"
    this.code = code
    this.start = range?.start
    this.end = range?.end
    this.incomplete = range?.incomplete
  }
}

// ---------------------------------------------------------------------------
// Tokens
// ---------------------------------------------------------------------------

export type CalcTokenType =
  | "equals"
  | "number"
  | "string"
  | "boolean"
  | "name"
  | "reference"
  | "colon"
  | "function"
  | "operator"
  | "percent"
  | "paren"
  | "separator"
  | "space"
  | "unknown"

export type CalcToken = {
  type: CalcTokenType
  text: string
  start: number
  end: number
}

const NUMBER = /^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/
const NAME = /^[\p{L}_][\p{L}\p{N}_.]*/u
/** A1-style cell: up to three letters then digits, either side pinned with $. */
const REFERENCE = /^\$?[A-Za-z]{1,3}\$?\d+(?![\p{L}\p{N}_.(])/u
const REFERENCE_PARTS = /^\$?([A-Za-z]{1,3})\$?(\d+)$/
const SPACE = /^\s+/
const OPERATORS = ["<=", ">=", "<>", "+", "-", "*", "/", "^", "&", "=", "<", ">", "×", "÷"]
const OPERATOR_ALIASES: Record<string, string> = { "×": "*", "÷": "/" }

/**
 * Splits a formula into tokens. Joining every token's text gives the input
 * back, spaces included, so the list can drive syntax highlighting.
 */
export function tokenizesFormula(formula: string): CalcToken[] {
  const tokens: CalcToken[] = []
  let index = 0

  const pushes = (type: CalcTokenType, text: string) => {
    tokens.push({ type, text, start: index, end: index + text.length })
    index += text.length
  }

  while (index < formula.length) {
    const rest = formula.slice(index)
    const char = rest[0]

    const space = SPACE.exec(rest)
    if (space) {
      pushes("space", space[0])
      continue
    }

    // A leading "=" marks a formula; it is not the equality operator.
    if (char === "=" && tokens.every((token) => token.type === "space")) {
      pushes("equals", "=")
      continue
    }

    const number = NUMBER.exec(rest)
    if (number) {
      pushes("number", number[0])
      continue
    }

    if (char === '"') {
      let end = 1
      while (end < rest.length) {
        if (rest[end] === '"') {
          if (rest[end + 1] === '"') end += 2
          else {
            end += 1
            break
          }
        } else end += 1
      }
      pushes("string", rest.slice(0, end))
      continue
    }

    const reference = REFERENCE.exec(rest)
    if (reference) {
      pushes("reference", reference[0])
      continue
    }

    const name = NAME.exec(rest)
    if (name) {
      const after = rest.slice(name[0].length).trimStart()
      const upper = name[0].toUpperCase()
      if (after.startsWith("(")) pushes("function", name[0])
      else if (upper === "TRUE" || upper === "FALSE") pushes("boolean", name[0])
      else pushes("name", name[0])
      continue
    }

    const operator = OPERATORS.find((candidate) => rest.startsWith(candidate))
    if (operator) {
      pushes("operator", operator)
      continue
    }

    if (char === "%") pushes("percent", char)
    else if (char === "(" || char === ")") pushes("paren", char)
    else if (char === "," || char === ";") pushes("separator", char)
    else if (char === ":") pushes("colon", char)
    else pushes("unknown", char)
  }

  return tokens
}

// ---------------------------------------------------------------------------
// Parser
// ---------------------------------------------------------------------------

type Node = { start: number; end: number } & (
  | { kind: "number"; value: number }
  | { kind: "string"; value: string }
  | { kind: "boolean"; value: boolean }
  | { kind: "name"; name: string; reference?: boolean }
  | { kind: "range"; from: string; to: string }
  | { kind: "call"; name: string; args: Node[] }
  | { kind: "unary"; operator: string; operand: Node }
  | { kind: "percent"; operand: Node }
  | { kind: "binary"; operator: string; left: Node; right: Node }
)

/** [left, right] binding power. Right-associative when right < left. */
const BINARY: Record<string, [number, number]> = {
  "=": [1, 2],
  "<>": [1, 2],
  "<": [1, 2],
  ">": [1, 2],
  "<=": [1, 2],
  ">=": [1, 2],
  "&": [3, 4],
  "+": [5, 6],
  "-": [5, 6],
  "*": [7, 8],
  "/": [7, 8],
  "^": [10, 9],
}
const UNARY_POWER = 9
const PERCENT_POWER = 11

function parsesFormula(formula: string): Node {
  const tokens = tokenizesFormula(formula).filter(
    (token) => token.type !== "space" && token.type !== "equals"
  )
  let position = 0

  const peek = () => tokens[position]
  const ends = () =>
    new CalcError("#ERROR!", "The formula ends too early.", {
      start: formula.length,
      end: formula.length,
      incomplete: true,
    })
  const unexpected = (token: CalcToken) =>
    new CalcError("#ERROR!", `Unexpected "${token.text}".`, token)

  function parsesPrefix(): Node {
    const token = tokens[position++]
    if (!token) throw ends()

    switch (token.type) {
      case "number":
        return { kind: "number", value: Number(token.text), ...span(token) }
      case "string": {
        if (token.text.length < 2 || !token.text.endsWith('"')) {
          throw new CalcError("#ERROR!", "Text is missing its closing quote.", {
            ...span(token),
            incomplete: true,
          })
        }
        const value = token.text.slice(1, -1).replace(/""/g, '"')
        return { kind: "string", value, ...span(token) }
      }
      case "boolean":
        return {
          kind: "boolean",
          value: token.text.toUpperCase() === "TRUE",
          ...span(token),
        }
      case "name":
        return { kind: "name", name: token.text, ...span(token) }
      case "reference": {
        if (peek()?.type !== "colon") {
          return { kind: "name", name: token.text, reference: true, ...span(token) }
        }
        position += 1 // ":"
        const to = tokens[position++]
        if (!to) throw ends()
        if (to.type !== "reference") throw unexpected(to)
        return { kind: "range", from: token.text, to: to.text, start: token.start, end: to.end }
      }
      case "function": {
        position += 1 // "("
        const args: Node[] = []
        if (peek()?.text === ")") {
          const close = tokens[position++]
          return { kind: "call", name: token.text, args, start: token.start, end: close.end }
        }
        while (true) {
          args.push(parsesExpression(0))
          const next = tokens[position++]
          if (!next) {
            throw new CalcError("#ERROR!", `${token.text.toUpperCase()}( is missing its ")".`, {
              start: token.start,
              end: formula.length,
              incomplete: true,
            })
          }
          if (next.text === ")") {
            return { kind: "call", name: token.text, args, start: token.start, end: next.end }
          }
          if (next.type !== "separator") throw unexpected(next)
        }
      }
      case "paren": {
        if (token.text !== "(") throw unexpected(token)
        const inner = parsesExpression(0)
        const close = tokens[position++]
        if (!close) {
          throw new CalcError("#ERROR!", 'A "(" is missing its ")".', {
            start: token.start,
            end: formula.length,
            incomplete: true,
          })
        }
        if (close.text !== ")") throw unexpected(close)
        return { ...inner, start: token.start, end: close.end }
      }
      case "operator": {
        if (token.text !== "+" && token.text !== "-") throw unexpected(token)
        const operand = parsesExpression(UNARY_POWER)
        return { kind: "unary", operator: token.text, operand, start: token.start, end: operand.end }
      }
      case "unknown":
        throw new CalcError("#ERROR!", `"${token.text}" isn't allowed in a formula.`, token)
      default:
        throw unexpected(token)
    }
  }

  function parsesExpression(minPower: number): Node {
    let left = parsesPrefix()

    while (true) {
      const token = peek()
      if (!token) break

      if (token.type === "percent") {
        if (PERCENT_POWER < minPower) break
        position += 1
        left = { kind: "percent", operand: left, start: left.start, end: token.end }
        continue
      }

      if (token.type !== "operator") break
      const operator = OPERATOR_ALIASES[token.text] ?? token.text
      const [leftPower, rightPower] = BINARY[operator]
      if (leftPower < minPower) break
      position += 1
      const right = parsesExpression(rightPower)
      left = { kind: "binary", operator, left, right, start: left.start, end: right.end }
    }

    return left
  }

  if (tokens.length === 0) throw ends()
  const tree = parsesExpression(0)
  const extra = peek()
  if (extra) throw unexpected(extra)
  return tree
}

function span(token: CalcToken) {
  return { start: token.start, end: token.end }
}

// ---------------------------------------------------------------------------
// Coercion
// ---------------------------------------------------------------------------

/** Drops float noise the way a spreadsheet does: 0.1 + 0.2 is 0.3. */
function normalizes(value: number) {
  if (!Number.isFinite(value)) {
    throw new CalcError("#NUM!", "The result is too large to show.")
  }
  return Number(value.toPrecision(15)) || 0
}

function scalarOf(value: CalcArg, what = "a single value"): CalcValue {
  if (Array.isArray(value)) {
    throw new CalcError("#VALUE!", `A list can't be used as ${what}. Wrap it in SUM() or similar.`)
  }
  return value
}

/** TRUE is 1, FALSE is 0, "12" is 12, "" is 0. Other text is #VALUE!. */
export function toCalcNumber(value: CalcArg): number {
  const scalar = scalarOf(value, "a number")
  if (typeof scalar === "number") return scalar
  if (typeof scalar === "boolean") return scalar ? 1 : 0
  const trimmed = scalar.trim()
  if (trimmed === "") return 0
  const literal = readsLiteral(trimmed)
  if (typeof literal === "number") return literal
  throw new CalcError("#VALUE!", `"${scalar}" isn't a number.`)
}

export function toCalcText(value: CalcArg): string {
  const scalar = scalarOf(value, "text")
  if (typeof scalar === "string") return scalar
  return formatsCalcValue(scalar)
}

export function toCalcBoolean(value: CalcArg): boolean {
  const scalar = scalarOf(value, "TRUE or FALSE")
  if (typeof scalar === "boolean") return scalar
  if (typeof scalar === "number") return scalar !== 0
  const upper = scalar.trim().toUpperCase()
  if (upper === "TRUE") return true
  if (upper === "FALSE") return false
  throw new CalcError("#VALUE!", `"${scalar}" isn't TRUE or FALSE.`)
}

/** Default display: 15 significant digits, TRUE/FALSE in capitals. */
export function formatsCalcValue(value: CalcValue): string {
  if (typeof value === "boolean") return value ? "TRUE" : "FALSE"
  if (typeof value === "number") return String(Number(value.toPrecision(15)) || 0)
  return value
}

const LITERAL_NUMBER = /^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?%?$/

/** What a spreadsheet makes of typed text that isn't a formula. */
function readsLiteral(text: string): CalcValue {
  const trimmed = text.trim()
  if (LITERAL_NUMBER.test(trimmed)) {
    return trimmed.endsWith("%")
      ? normalizes(Number(trimmed.slice(0, -1)) / 100)
      : Number(trimmed)
  }
  const upper = trimmed.toUpperCase()
  if (upper === "TRUE") return true
  if (upper === "FALSE") return false
  return text
}

/** Numbers in the arguments: lists keep only their numbers, single values are coerced. */
function numbersIn(args: CalcArg[]) {
  const numbers: number[] = []
  for (const arg of args) {
    if (Array.isArray(arg)) {
      for (const item of arg) if (typeof item === "number") numbers.push(item)
    } else numbers.push(toCalcNumber(arg))
  }
  return numbers
}

function booleansIn(args: CalcArg[]) {
  const booleans: boolean[] = []
  for (const arg of args) {
    if (Array.isArray(arg)) {
      for (const item of arg) {
        if (typeof item === "boolean") booleans.push(item)
        else if (typeof item === "number") booleans.push(item !== 0)
      }
    } else booleans.push(toCalcBoolean(arg))
  }
  return booleans
}

function compares(left: CalcValue, right: CalcValue) {
  // Spreadsheet order across types: numbers < text < booleans.
  const rank = (value: CalcValue) =>
    typeof value === "number" ? 0 : typeof value === "string" ? 1 : 2
  if (rank(left) !== rank(right)) return rank(left) - rank(right)
  if (typeof left === "string") {
    return left.localeCompare(right as string, undefined, { sensitivity: "accent" })
  }
  return Number(left) - Number(right)
}

// ---------------------------------------------------------------------------
// Built-in functions
// ---------------------------------------------------------------------------

type BuiltIn = { min: number; max: number; run: (args: CalcArg[]) => CalcValue }

function rounds(value: number, digits: number, mode: "nearest" | "up" | "down") {
  const factor = 10 ** Math.trunc(digits)
  const scaled = Number((Math.abs(value) * factor).toPrecision(15))
  const whole =
    mode === "nearest" ? Math.round(scaled) : mode === "up" ? Math.ceil(scaled) : Math.floor(scaled)
  return normalizes((Math.sign(value) * whole) / factor)
}

function positive(value: number, name: string) {
  if (value <= 0) throw new CalcError("#NUM!", `${name} needs a number above 0.`)
  return value
}

const n = toCalcNumber

const BUILT_INS: Record<string, BuiltIn> = {
  // Aggregates
  SUM: { min: 1, max: Infinity, run: (args) => numbersIn(args).reduce((a, b) => a + b, 0) },
  PRODUCT: { min: 1, max: Infinity, run: (args) => numbersIn(args).reduce((a, b) => a * b, 1) },
  AVERAGE: {
    min: 1,
    max: Infinity,
    run: (args) => {
      const numbers = numbersIn(args)
      if (numbers.length === 0) throw new CalcError("#DIV/0!", "AVERAGE has no numbers to average.")
      return numbers.reduce((a, b) => a + b, 0) / numbers.length
    },
  },
  MEDIAN: {
    min: 1,
    max: Infinity,
    run: (args) => {
      const numbers = numbersIn(args).sort((a, b) => a - b)
      if (numbers.length === 0) throw new CalcError("#NUM!", "MEDIAN has no numbers.")
      const middle = Math.floor(numbers.length / 2)
      return numbers.length % 2 ? numbers[middle] : (numbers[middle - 1] + numbers[middle]) / 2
    },
  },
  MIN: { min: 1, max: Infinity, run: (args) => { const v = numbersIn(args); return v.length ? Math.min(...v) : 0 } },
  MAX: { min: 1, max: Infinity, run: (args) => { const v = numbersIn(args); return v.length ? Math.max(...v) : 0 } },
  COUNT: {
    min: 1,
    max: Infinity,
    run: (args) =>
      args.flat().filter((value) => typeof value === "number").length,
  },

  // Maths
  ABS: { min: 1, max: 1, run: ([x]) => Math.abs(n(x)) },
  SIGN: { min: 1, max: 1, run: ([x]) => Math.sign(n(x)) },
  SQRT: {
    min: 1,
    max: 1,
    run: ([x]) => {
      const value = n(x)
      if (value < 0) throw new CalcError("#NUM!", "SQRT can't take a negative number.")
      return Math.sqrt(value)
    },
  },
  POWER: { min: 2, max: 2, run: ([x, y]) => n(x) ** n(y) },
  EXP: { min: 1, max: 1, run: ([x]) => Math.exp(n(x)) },
  LN: { min: 1, max: 1, run: ([x]) => Math.log(positive(n(x), "LN")) },
  LOG10: { min: 1, max: 1, run: ([x]) => Math.log10(positive(n(x), "LOG10")) },
  LOG: {
    min: 1,
    max: 2,
    run: ([x, base = 10]) => Math.log(positive(n(x), "LOG")) / Math.log(positive(n(base), "LOG")),
  },
  MOD: {
    min: 2,
    max: 2,
    run: ([x, y]) => {
      const divisor = n(y)
      if (divisor === 0) throw new CalcError("#DIV/0!", "MOD can't divide by zero.")
      // The sign follows the divisor, as in a spreadsheet.
      return n(x) - divisor * Math.floor(n(x) / divisor)
    },
  },
  ROUND: { min: 1, max: 2, run: ([x, d = 0]) => rounds(n(x), n(d), "nearest") },
  ROUNDUP: { min: 1, max: 2, run: ([x, d = 0]) => rounds(n(x), n(d), "up") },
  ROUNDDOWN: { min: 1, max: 2, run: ([x, d = 0]) => rounds(n(x), n(d), "down") },
  TRUNC: { min: 1, max: 2, run: ([x, d = 0]) => rounds(n(x), n(d), "down") },
  INT: { min: 1, max: 1, run: ([x]) => Math.floor(n(x)) },
  CEILING: {
    min: 1,
    max: 2,
    run: ([x, step = 1]) => (n(step) === 0 ? 0 : Math.ceil(n(x) / n(step)) * n(step)),
  },
  FLOOR: {
    min: 1,
    max: 2,
    run: ([x, step = 1]) => (n(step) === 0 ? 0 : Math.floor(n(x) / n(step)) * n(step)),
  },
  PI: { min: 0, max: 0, run: () => Math.PI },
  SIN: { min: 1, max: 1, run: ([x]) => Math.sin(n(x)) },
  COS: { min: 1, max: 1, run: ([x]) => Math.cos(n(x)) },
  TAN: { min: 1, max: 1, run: ([x]) => Math.tan(n(x)) },
  ASIN: { min: 1, max: 1, run: ([x]) => Math.asin(n(x)) },
  ACOS: { min: 1, max: 1, run: ([x]) => Math.acos(n(x)) },
  ATAN: { min: 1, max: 1, run: ([x]) => Math.atan(n(x)) },
  RADIANS: { min: 1, max: 1, run: ([x]) => (n(x) * Math.PI) / 180 },
  DEGREES: { min: 1, max: 1, run: ([x]) => (n(x) * 180) / Math.PI },

  // Logic (IF and IFERROR are handled lazily by the evaluator)
  AND: { min: 1, max: Infinity, run: (args) => booleansIn(args).every(Boolean) },
  OR: { min: 1, max: Infinity, run: (args) => booleansIn(args).some(Boolean) },
  NOT: { min: 1, max: 1, run: ([x]) => !toCalcBoolean(x) },

  // Text
  CONCAT: {
    min: 1,
    max: Infinity,
    run: (args) => args.flat().map((value) => toCalcText(value)).join(""),
  },
  LEN: { min: 1, max: 1, run: ([x]) => toCalcText(x).length },
  UPPER: { min: 1, max: 1, run: ([x]) => toCalcText(x).toUpperCase() },
  LOWER: { min: 1, max: 1, run: ([x]) => toCalcText(x).toLowerCase() },
  TRIM: { min: 1, max: 1, run: ([x]) => toCalcText(x).trim().replace(/\s+/g, " ") },
  LEFT: { min: 1, max: 2, run: ([x, count = 1]) => toCalcText(x).slice(0, Math.max(0, n(count))) },
  RIGHT: {
    min: 1,
    max: 2,
    run: ([x, count = 1]) => {
      const text = toCalcText(x)
      return text.slice(Math.max(0, text.length - Math.max(0, n(count))))
    },
  },
}

const LAZY = ["IF", "IFERROR"]

/** Every built-in function name, for autocomplete or docs. */
export const CALC_FUNCTION_NAMES = [...Object.keys(BUILT_INS), ...LAZY].sort()

// ---------------------------------------------------------------------------
// Evaluation
// ---------------------------------------------------------------------------

type Scope = {
  variables: Map<string, { key: string; value: CalcVariable }>
  functions: Map<string, CalcFunction>
  cache: Map<string, CalcArg>
  /** Variables whose formula failed, so a sheet reports each error once. */
  failures: Map<string, CalcError>
  resolving: string[]
  dependencies: Set<string>
  references: boolean
}

function createsScope(options: CalcOptions): Scope {
  const variables = new Map<string, { key: string; value: CalcVariable }>()
  for (const [key, value] of Object.entries(options.variables ?? {})) {
    variables.set(key.toLowerCase(), { key, value })
  }
  const functions = new Map<string, CalcFunction>()
  for (const [key, run] of Object.entries(options.functions ?? {})) {
    functions.set(key.toUpperCase(), run)
  }
  return {
    variables,
    functions,
    cache: new Map(),
    failures: new Map(),
    resolving: [],
    dependencies: new Set(),
    references: options.references ?? false,
  }
}

function resolvesName(node: Node & { kind: "name" }, scope: Scope, top: boolean): CalcArg {
  // $ only pins a reference when it is copied; B$2 and B2 are the same cell.
  const name = node.reference ? node.name.replace(/\$/g, "") : node.name
  const lower = name.toLowerCase()
  const entry = scope.variables.get(lower)
  if (!entry) {
    if (node.reference && scope.references) {
      if (top) scope.dependencies.add(name.toUpperCase())
      return ""
    }
    throw new CalcError("#NAME?", `Unknown name "${node.name}".`, node)
  }
  if (top) scope.dependencies.add(entry.key)

  const cached = scope.cache.get(lower)
  if (cached !== undefined) return cached
  const failed = scope.failures.get(lower)
  if (failed) throw new CalcError(failed.code, failed.message, node)

  const { key, value } = entry
  let resolved: CalcArg
  if (typeof value === "string" && value.trimStart().startsWith("=")) {
    if (scope.resolving.includes(lower)) {
      const loop = [...scope.resolving.slice(scope.resolving.indexOf(lower)), lower]
        .map((name) => scope.variables.get(name)?.key ?? name)
        .join(" → ")
      throw new CalcError("#CIRC!", `Circular reference: ${loop}.`, node)
    }
    scope.resolving.push(lower)
    try {
      resolved = evaluatesNode(parsesFormula(value), scope, false)
    } catch (error) {
      if (!(error instanceof CalcError)) throw error
      // Point at the name here; a range inside its own formula means nothing to this one.
      const message = error.code === "#CIRC!" ? error.message : `In ${key}: ${error.message}`
      const failure = new CalcError(error.code, message, node)
      scope.failures.set(lower, failure)
      throw failure
    } finally {
      scope.resolving.pop()
    }
  } else if (typeof value === "number") {
    resolved = normalizes(value)
  } else {
    resolved = value
  }

  scope.cache.set(lower, resolved)
  return resolved
}

const MAX_RANGE_CELLS = 100_000

function readsReference(text: string) {
  const [, letters, digits] = REFERENCE_PARTS.exec(text) ?? []
  let col = 0
  for (const letter of letters.toUpperCase()) col = col * 26 + letter.charCodeAt(0) - 64
  return { col: col - 1, row: Number(digits) - 1 }
}

function columnLettersOf(index: number) {
  let letters = ""
  for (let at = index + 1; at > 0; at = Math.floor((at - 1) / 26)) {
    letters = String.fromCharCode(65 + ((at - 1) % 26)) + letters
  }
  return letters
}

/** A1:C3 as a flat list, row by row. Empty cells are left out, as SUM expects. */
function resolvesRange(node: Node & { kind: "range" }, scope: Scope, top: boolean): CalcValue[] {
  const a = readsReference(node.from)
  const b = readsReference(node.to)
  const top_ = Math.min(a.row, b.row)
  const bottom = Math.max(a.row, b.row)
  const left = Math.min(a.col, b.col)
  const right = Math.max(a.col, b.col)
  if ((bottom - top_ + 1) * (right - left + 1) > MAX_RANGE_CELLS) {
    throw new CalcError("#VALUE!", "That range is too large.", node)
  }

  const values: CalcValue[] = []
  for (let row = top_; row <= bottom; row += 1) {
    for (let col = left; col <= right; col += 1) {
      const name = `${columnLettersOf(col)}${row + 1}`
      if (top) scope.dependencies.add(scope.variables.get(name.toLowerCase())?.key ?? name)
      if (!scope.variables.has(name.toLowerCase())) continue
      const value = resolvesName(
        { kind: "name", name, reference: true, start: node.start, end: node.end },
        scope,
        false
      )
      if (Array.isArray(value)) values.push(...value)
      else if (value !== "") values.push(value)
    }
  }
  return values
}

function callsFunction(node: Node & { kind: "call" }, scope: Scope, top: boolean): CalcValue {
  const upper = node.name.toUpperCase()
  const custom = scope.functions.get(upper)
  const evaluates = (arg: Node) => evaluatesNode(arg, scope, top)

  if (!custom && upper === "IF") {
    checksArgCount(node, 2, 3)
    const [condition, then, otherwise] = node.args
    if (toCalcBoolean(evaluates(condition))) return scalarOf(evaluates(then))
    return otherwise ? scalarOf(evaluates(otherwise)) : false
  }
  if (!custom && upper === "IFERROR") {
    checksArgCount(node, 2, 2)
    try {
      return scalarOf(evaluates(node.args[0]))
    } catch (error) {
      if (!(error instanceof CalcError) || error.code === "#ERROR!") throw error
      return scalarOf(evaluates(node.args[1]))
    }
  }

  const builtIn = BUILT_INS[upper]
  if (!custom && !builtIn) {
    throw new CalcError("#NAME?", `Unknown function "${node.name}".`, {
      start: node.start,
      end: node.start + node.name.length,
    })
  }
  if (!custom) checksArgCount(node, builtIn.min, builtIn.max)

  const args = node.args.map(evaluates)
  let value: CalcValue
  try {
    value = custom ? custom(...args) : builtIn.run(args)
  } catch (error) {
    if (error instanceof CalcError) {
      if (error.start === undefined) {
        error.start = node.start
        error.end = node.end
      }
      throw error
    }
    throw new CalcError("#VALUE!", `${upper}: ${error instanceof Error ? error.message : String(error)}`, node)
  }
  if (typeof value === "number") return normalizes(value)
  if (typeof value === "string" || typeof value === "boolean") return value
  throw new CalcError("#VALUE!", `${upper} didn't return a value.`, node)
}

function checksArgCount(node: Node & { kind: "call" }, min: number, max: number) {
  const count = node.args.length
  if (count >= min && count <= max) return
  const name = node.name.toUpperCase()
  const expected =
    min === max
      ? `${min} argument${min === 1 ? "" : "s"}`
      : max === Infinity
        ? `at least ${min} argument${min === 1 ? "" : "s"}`
        : `${min} to ${max} arguments`
  throw new CalcError("#VALUE!", `${name} takes ${expected}, not ${count}.`, node)
}

function evaluatesNode(node: Node, scope: Scope, top: boolean): CalcArg {
  switch (node.kind) {
    case "number":
    case "string":
    case "boolean":
      return node.value
    case "name":
      return resolvesName(node, scope, top)
    case "range":
      return resolvesRange(node, scope, top)
    case "call":
      return callsFunction(node, scope, top)
    case "percent":
      return normalizes(toCalcNumber(evaluatesNode(node.operand, scope, top)) / 100)
    case "unary": {
      const value = toCalcNumber(evaluatesNode(node.operand, scope, top))
      return node.operator === "-" ? -value || 0 : value
    }
    case "binary": {
      const left = evaluatesNode(node.left, scope, top)
      const right = evaluatesNode(node.right, scope, top)
      try {
        return appliesOperator(node.operator, left, right)
      } catch (error) {
        if (error instanceof CalcError && error.start === undefined) {
          error.start = node.start
          error.end = node.end
        }
        throw error
      }
    }
  }
}

function appliesOperator(operator: string, left: CalcArg, right: CalcArg): CalcValue {
  if (operator === "&") return toCalcText(left) + toCalcText(right)

  if (["=", "<>", "<", ">", "<=", ">="].includes(operator)) {
    const order = compares(scalarOf(left), scalarOf(right))
    switch (operator) {
      case "=": return order === 0
      case "<>": return order !== 0
      case "<": return order < 0
      case ">": return order > 0
      case "<=": return order <= 0
      default: return order >= 0
    }
  }

  const a = toCalcNumber(left)
  const b = toCalcNumber(right)
  switch (operator) {
    case "+": return normalizes(a + b)
    case "-": return normalizes(a - b)
    case "*": return normalizes(a * b)
    case "/":
      if (b === 0) throw new CalcError("#DIV/0!", "Can't divide by zero.")
      return normalizes(a / b)
    default: {
      if (a < 0 && !Number.isInteger(b)) {
        throw new CalcError("#NUM!", "A negative number can't take a fractional power.")
      }
      return normalizes(a ** b)
    }
  }
}

/**
 * Evaluates a formula. Never throws: problems come back as
 * `{ status: "error", error }` with an Excel-style code.
 */
export function evaluatesFormula(formula: string, options: CalcOptions = {}): CalcResult {
  const trimmed = formula.trim()
  const isFormula = trimmed.startsWith("=")

  if (trimmed === "" || trimmed === "=") {
    return { status: "empty", formula, dependencies: [] }
  }
  if (options.requireEquals && !isFormula) {
    return { status: "ok", formula, value: readsLiteral(formula), dependencies: [] }
  }

  const scope = createsScope(options)
  try {
    const value = scalarOf(evaluatesNode(parsesFormula(formula), scope, true), "the result")
    return { status: "ok", formula, value, dependencies: [...scope.dependencies] }
  } catch (error) {
    const info: CalcErrorInfo =
      error instanceof CalcError
        ? {
            code: error.code,
            message: error.message,
            start: error.start,
            end: error.end,
            incomplete: error.incomplete,
          }
        : { code: "#VALUE!", message: String(error) }
    return { status: "error", formula, error: info, dependencies: [...scope.dependencies] }
  }
}

/**
 * Works out every formula among the variables at once, sharing one cache, so
 * a sheet of cells that refer to each other is evaluated once per cell.
 * Returns a result for each variable whose value is a formula.
 */
export function evaluatesVariables(options: CalcOptions = {}): Record<string, CalcResult> {
  const scope = createsScope(options)
  const results: Record<string, CalcResult> = {}

  for (const [key, formula] of Object.entries(options.variables ?? {})) {
    if (typeof formula !== "string" || !formula.trimStart().startsWith("=")) continue
    const lower = key.toLowerCase()
    scope.dependencies = new Set()
    scope.resolving = [lower]
    try {
      const failed = scope.failures.get(lower)
      if (failed) throw failed
      const value = scalarOf(evaluatesNode(parsesFormula(formula), scope, true), "the result")
      scope.cache.set(lower, value)
      results[key] = { status: "ok", formula, value, dependencies: [...scope.dependencies] }
    } catch (error) {
      const info: CalcErrorInfo =
        error instanceof CalcError
          ? { code: error.code, message: error.message, start: error.start, end: error.end, incomplete: error.incomplete }
          : { code: "#VALUE!", message: String(error) }
      if (error instanceof CalcError) {
        const message = error.code === "#CIRC!" ? error.message : `In ${key}: ${error.message}`
        scope.failures.set(lower, new CalcError(error.code, message))
      }
      results[key] = { status: "error", formula, error: info, dependencies: [...scope.dependencies] }
    }
  }

  return results
}

/**
 * Turns a result back into text that evaluates to the same value, e.g. to
 * replace `=2*21` with `42` when the field commits.
 */
export function toFormulaText(value: CalcValue, requireEquals = false) {
  if (typeof value === "string") {
    return requireEquals ? value : `"${value.replace(/"/g, '""')}"`
  }
  return formatsCalcValue(value)
}
